/bin/bash -lc "node --input-type=module <<'NODE'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { performance } from 'node:perf_hooks'

let receivedEvent
let collectorFinished = false
const collector = createServer(async (request, response) => {
  const chunks = []
  for await (const chunk of request) chunks.push(chunk)
  receivedEvent = JSON.parse(Buffer.concat(chunks).toString())
  setTimeout(() => {
    collectorFinished = true
    response.writeHead(200)
    response.end('ok')
  }, 1500)
})
await new Promise((resolve) => collector.listen(0, '127.0.0.1', resolve))
const endpoint = "'`http://127.0.0.1:${collector.address().port}/events`
const app = spawn(process.execPath, ['"'node_modules/next/dist/bin/next', 'start', '-p', '3100'], {
  cwd: process.cwd(),
  env: { ...process.env, ANALYTICS_ENDPOINT: endpoint },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let appOutput = ''
app.stdout.on('data', (chunk) => { appOutput += chunk.toString() })
app.stderr.on('data', (chunk) => { appOutput += chunk.toString() })
try {
  const deadline = Date.now() + 15000
  while ("'!appOutput.includes('"'Ready') && Date.now() < deadline) {
    if (app.exitCode "'!== null) throw new Error(`Next exited: ${appOutput}`)
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  if (!appOutput.includes('"'Ready')) throw new Error("'`Next did not start: ${appOutput}`)

  const start = performance.now()
  const response = await fetch('"'http://127.0.0.1:3100/')
  const html = await response.text()
  const elapsed = Math.round(performance.now() - start)
  if ("'!response.ok || !html.includes('"'Welcome to our site.')) throw new Error('Welcome page failed')
  if (collectorFinished) throw new Error('Analytics completed before the page response')
  if (elapsed >= 1500) throw new Error("'`Page response waited ${elapsed} ms for analytics`)

  const waitUntil = Date.now() + 5000
  while (!collectorFinished && Date.now() < waitUntil) {
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  if (!collectorFinished || receivedEvent?.event !== '"'page_view' || receivedEvent?.path "'!== '"'/') {
    throw new Error("'`Analytics event failed: ${JSON.stringify(receivedEvent)}`)
  }
  console.log(`Welcome response: ${elapsed} ms; delayed analytics request completed afterward.`)
  console.log(`Analytics event: ${JSON.stringify(receivedEvent)}`)
} finally {
  app.kill('"'SIGTERM')
  collector.close()
}
NODE"
